import React,{useCallback,useEffect,useMemo,useRef,useState}from'react';
import{Activity,AlertCircle,Bell,BookOpen,Bot,CheckCircle2,Clock3,Eye,EyeOff,FileText,Grid2X2,Home,KeyRound,Laptop,LogOut,Moon,MonitorDown,Search,Send,Settings,ShieldCheck,Sun,Ticket,UserCircle2,Users,X}from'lucide-react';
import {startPolling} from './polling.js';
import {requestApi, isConnectionError, SESSION_ERROR} from './api.js';
import {attachPageGestures} from './gestures.js';
import {validatedSsprUrl, validatedMicrosoftPasswordActionUrl} from './sspr.js';
import {CHAT_MESSAGE_LIMIT, chatComposerState} from './chat.js';
import PaginatedRows from './pagination.jsx';
import {EmployeeAccess, AdminAccess} from './Access.jsx';

const keepIfEqual=(current,next)=>JSON.stringify(current)===JSON.stringify(next)?current:next;
const sessionKey='autodeskai.session.token';
const themeKey='autodeskai.theme';
const readTheme=()=>{try{const saved=window.localStorage.getItem(themeKey);return saved==='dark'||saved==='light'?saved:window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}catch{return'light'}};
document.documentElement.dataset.theme=readTheme();
const readStoredToken=()=>{try{return window.sessionStorage.getItem(sessionKey)||''}catch{return''}};
const storeToken=value=>{try{if(value)window.sessionStorage.setItem(sessionKey,value);else window.sessionStorage.removeItem(sessionKey)}catch{/* Private browsing can block storage. */}};

const label=x=>(x||'PENDING').replaceAll('_',' ');
const title=x=>({SOFTWARE_INSTALL:'Software Installation',ACCESS_REQUEST:'Application Access',PASSWORD_RESET:'Password Reset',PASSWORD_CHANGE:'Password Change',CLARIFICATION:'More Information Needed'}[x.intent]||'IT Support Request');
const icon=x=>x.intent==='SOFTWARE_INSTALL'?MonitorDown:x.intent==='ACCESS_REQUEST'?Grid2X2:x.intent?.startsWith('PASSWORD_')?KeyRound:Ticket;
const initials=x=>(x||'User').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const parseDate=value=>new Date(/(?:Z|[+-]\d{2}:\d{2})$/i.test(value)?value:value+'Z');
const formatDate=value=>{if(!value)return'—';const date=parseDate(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString();};
const formatShortDate=value=>{if(!value)return'—';const date=parseDate(value);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString();};
const deviceOnline=device=>{const lastSeen=parseDate(device.last_seen);return device.status==='ACTIVE'&&!Number.isNaN(lastSeen.getTime())&&Date.now()-lastSeen.getTime()<=120000;};

export default function App(){
 const[theme,setTheme]=useState(readTheme);
 useEffect(()=>{document.documentElement.dataset.theme=theme;try{window.localStorage.setItem(themeKey,theme)}catch{/* Storage may be unavailable. */}},[theme]);
 const[token,setToken]=useState(readStoredToken),[user,setUser]=useState(null),[mode,setMode]=useState('login');
 const[restoring,setRestoring]=useState(Boolean(token)),[restoreError,setRestoreError]=useState(''),[restoreAttempt,setRestoreAttempt]=useState(0);
 const[requests,setRequests]=useState([]),[devices,setDevices]=useState([]),[chat,setChat]=useState([]),[msg,setMsg]=useState(''),[search,setSearch]=useState(''),[selectedDevice,setSelectedDevice]=useState(''),[clarify,setClarify]=useState(null),[retryKey,setRetryKey]=useState(null);
 const[busy,setBusy]=useState(false),[error,setError]=useState(''),[retryUntil,setRetryUntil]=useState(0),[retryTick,setRetryTick]=useState(0),[modal,setModal]=useState(null),[admin,setAdmin]=useState({users:[],requests:[],devices:[],audit:[]}),[catalog,setCatalog]=useState({software:[],applications:[]}),[enrollment,setEnrollment]=useState(null),[authRole,setAuthRole]=useState('employee');
 const session=useRef(token),employeePoll=useRef(null),adminPoll=useRef(null),pageHistory=useRef({pages:['Dashboard'],index:0}),actionVersion=useRef(0),acting=useRef(false);
 const setActive=useCallback(page=>{const history=pageHistory.current,current=history.pages[history.index];if(page===current)return;const pages=[...history.pages.slice(0,history.index+1),page].slice(-100);pageHistory.current={pages,index:pages.length-1};setActiveState(page)},[]);
 const goPage=useCallback(direction=>{const history=pageHistory.current,index=Math.max(0,Math.min(history.pages.length-1,history.index+direction));if(index===history.index)return;pageHistory.current={...history,index};setActiveState(history.pages[index])},[]);
 const[active,setActiveState]=useState('Dashboard');
 const activeRef=useRef(active);activeRef.current=active;
 useEffect(()=>{if(!retryUntil)return;const timer=setInterval(()=>{setRetryTick(tick=>tick+1);if(Date.now()>=retryUntil)setRetryUntil(0)},250);return()=>clearInterval(timer)},[retryUntil]);
 const retryAfter=Math.max(0,Math.ceil((retryUntil-Date.now())/1000));
 useEffect(()=>{if(user)return attachPageGestures(window,goPage)},[user?.id,goPage]);
 const logout=useCallback(()=>{session.current='';storeToken('');actionVersion.current++;acting.current=false;employeePoll.current?.stop();adminPoll.current?.stop();pageHistory.current={pages:['Dashboard'],index:0};setToken('');setUser(null);setRestoring(false);setRestoreError('');setBusy(false);setError('');setRetryUntil(0);setRetryTick(0);setRequests([]);setDevices([]);setChat([]);setAdmin({users:[],requests:[],devices:[],audit:[]});setCatalog({software:[],applications:[]});setEnrollment(null);setModal(null);setMsg('');setSearch('');setSelectedDevice('');setClarify(null);setRetryKey(null);setActiveState('Dashboard')},[]);
 const api=useCallback(async(path,options={})=>{try{const data=await requestApi(path,{token,...options});if(token&&session.current!==token)throw new DOMException('Aborted','AbortError');return data}catch(e){if(token&&session.current!==token)throw new DOMException('Aborted','AbortError');if(e.status===401&&token){logout();setError(SESSION_ERROR)}throw e}},[token,logout]);
 useEffect(()=>{const saved=session.current;if(!saved)return;const controller=new AbortController();setRestoring(true);setRestoreError('');requestApi('/auth/me',{token:saved,signal:controller.signal}).then(profile=>{if(controller.signal.aborted||session.current!==saved)return;setUser(profile);setAuthRole(profile.role)}).catch(e=>{if(controller.signal.aborted||session.current!==saved)return;if(e.status===401){session.current='';storeToken('');setToken('');setError(SESSION_ERROR)}else setRestoreError(e.message)}).finally(()=>{if(!controller.signal.aborted)setRestoring(false)});return()=>controller.abort()},[restoreAttempt]);
 async function act(fn){if(acting.current)return;acting.current=true;const version=++actionVersion.current;setBusy(true);setError('');try{await fn()}catch(e){if(version===actionVersion.current&&e.name!=='AbortError'){setError(e.message);if(e.status===429&&Number.isFinite(e.retryAfter)&&e.retryAfter>0){setRetryTick(0);setRetryUntil(Date.now()+e.retryAfter*1000)}}}finally{if(version===actionVersion.current){acting.current=false;setBusy(false)}}}
 function clearBackendError(){setError(current=>isConnectionError(current)?'':current)}
 async function refreshAdmin(names=['requests','devices','users','catalog','audit']){await Promise.all(names.map(name=>adminPoll.current?.refresh(name)))}
 useEffect(()=>{if(!token||!user||user.role==='admin')return;
   const poll=startPolling([
     {name:'requests',interval:15000,load:async signal=>{const rows=await api('/requests',{signal});if(!signal.aborted&&session.current===token){setRequests(current=>keepIfEqual(current,rows));clearBackendError()}return rows.some(row=>['PENDING','PROCESSING','AWAITING_ADMIN'].includes(row.status))}},
     {name:'devices',interval:60000,load:async signal=>{const rows=await api('/devices',{signal});if(!signal.aborted&&session.current===token){setDevices(current=>keepIfEqual(current,rows));clearBackendError()}}},
   ],{onError:e=>setError(e.message)});
   employeePoll.current=poll;
   return()=>{poll.stop();if(employeePoll.current===poll)employeePoll.current=null};
 },[token,user?.role]);
 useEffect(()=>{if(!token||!user||user.role!=='admin')return;
   const loadRows=(name,path)=>async signal=>{if(name==='audit'&&activeRef.current!=='Audit Logs')return;const rows=await api(path,{signal});if(!signal.aborted&&session.current===token){setAdmin(current=>{const next=keepIfEqual(current[name],rows);return next===current[name]?current:{...current,[name]:next}});clearBackendError()}};
   const poll=startPolling([
     {name:'requests',interval:15000,load:loadRows('requests','/admin/requests')},
     {name:'users',interval:60000,load:loadRows('users','/admin/users')},
     {name:'devices',interval:60000,load:loadRows('devices','/admin/devices')},
     {name:'audit',interval:30000,load:loadRows('audit','/admin/audit')},
     {name:'catalog',interval:120000,load:async signal=>{const rows=await api('/catalog',{signal});if(!signal.aborted&&session.current===token){setCatalog(current=>keepIfEqual(current,rows));clearBackendError()}}},
   ],{onError:e=>setError(e.message)});
   adminPoll.current=poll;
   return()=>{poll.stop();if(adminPoll.current===poll)adminPoll.current=null};
 },[token,user?.role]);
 useEffect(()=>{if(user?.role==='admin'&&active==='Audit Logs')void adminPoll.current?.refresh('audit')},[active,user?.role]);
 useEffect(()=>{if(user&&!chat.length)setChat([{r:'bot',t:`Hello ${user.name}! I can help with password reset or change, approved software installation, and application access.`}])},[user,chat.length]);
 async function authenticate(e){e.preventDefault();const f=new FormData(e.currentTarget),password=f.get('password'),loginRole=authRole;if(mode==='register'&&password!==f.get('confirm_password')){setError('Passwords do not match.');return}await act(async()=>{const r=mode==='register'?await api('/auth/register',{method:'POST',body:JSON.stringify({account_role:loginRole,...(loginRole==='admin'?{admin_invite_code:f.get('admin_invite_code')}:{ }),first_name:f.get('first_name'),last_name:f.get('last_name'),date_of_birth:f.get('date_of_birth'),username:f.get('username'),email:f.get('email'),password,confirm_password:f.get('confirm_password')})}):await api('/auth/login',{method:'POST',body:JSON.stringify({identifier:f.get('identifier'),password,expected_role:loginRole})});if(r.user.role!==loginRole)throw new Error('This account cannot sign in through the selected portal.');session.current=r.access_token;storeToken(r.access_token);setToken(r.access_token);setUser(r.user);setActive('Dashboard')})}
 async function send(text=msg){text=text.trim();if(!text||acting.current)return;setChat(c=>[...c,{r:'user',t:text}]);setMsg('');await act(async()=>{const payload={message:text,device_id:selectedDevice?Number(selectedDevice):null,previous_request_id:clarify},signature=JSON.stringify(payload),key=retryKey?.signature===signature?retryKey.key:crypto.randomUUID();setRetryKey({signature,key});const r=await api('/requests',{method:'POST',timeoutMs:120000,body:JSON.stringify({...payload,idempotency_key:key})});setRetryKey(null);if(r.intent!=='CHAT')setClarify(r.status==='NEEDS_CLARIFICATION'?r.id:null);setChat(c=>[...c,{r:'bot',t:r.message,id:r.id,status:r.status}]);if(r.intent!=='CHAT')await employeePoll.current?.refresh('requests')})}
 async function passwordAction(id){await act(async()=>{const result=await api(`/requests/${id}/password/action`,{method:'POST'});const allowed=validatedMicrosoftPasswordActionUrl(result.url);if(!allowed)throw new Error('AutoDeskAI received an unapproved Microsoft password destination. Contact your IT administrator.');window.location.assign(allowed)})}
 const filtered=useMemo(()=>{const query=search.toLowerCase();return requests.filter(x=>(title(x)+x.status+x.message+x.original_message).toLowerCase().includes(query))},[requests,search]);
 const adminUserMap=useMemo(()=>Object.fromEntries(admin.users.map(employee=>[employee.id,employee])),[admin.users]);
 const filteredAdminRequests=useMemo(()=>{const query=search.toLowerCase();return admin.requests.map(request=>({...request,message:request.original_message&&request.original_message!=='[not retained]'?request.original_message:request.message})).filter(request=>`${request.id} ${request.intent} ${request.status} ${request.message} ${adminUserMap[request.user_id]?.name||''} ${adminUserMap[request.user_id]?.email||''}`.toLowerCase().includes(query))},[admin.requests,adminUserMap,search]);
 const openEnrollment=useCallback(()=>setActive('Admin Panel'),[setActive]);
 if(restoring)return <div className="authStatus" role="status">Restoring your session…</div>;
 if(restoreError)return <div className="authStatus" role="alert"><p>{restoreError}</p><button className="primary" type="button" onClick={()=>setRestoreAttempt(value=>value+1)}>Try again</button><button className="secondary" type="button" onClick={logout}>Sign out</button></div>;
 if(!user)return <Auth mode={mode} setMode={setMode} submit={authenticate} busy={busy} error={error} authRole={authRole} setAuthRole={setAuthRole} theme={theme} setTheme={setTheme}/>;
 const nav=user.role==='admin'?[['Dashboard',Home],['Admin Panel',Users],['Application Access',Grid2X2],['Audit Logs',Activity]]:[['Dashboard',Home],['My Requests',Ticket],['Application Access',Grid2X2],['Knowledge Base',BookOpen],['Settings',Settings]];
 const resolved=requests.filter(x=>x.status==='COMPLETED').length,progress=requests.filter(x=>['PENDING','PROCESSING','AWAITING_USER_ACTION','AWAITING_ADMIN','APPROVED_PROVISIONING_REQUIRED'].includes(x.status)).length,needs=requests.filter(x=>x.status==='NEEDS_CLARIFICATION').length;
 return <div className="app"><main><header className="appHeader"><div className="topBrand"><Brand/></div><div className="search"><Search size={18}/><input value={search} onChange={e=>{setSearch(e.target.value);if(e.target.value.trim())setActive(user.role==='admin'?'Admin Panel':'My Requests')}} placeholder="Search requests..." aria-label="Search requests"/></div><div className="headRight"><ThemeToggle theme={theme} setTheme={setTheme}/>{user.role!=='admin'&&<button className="bell" type="button" aria-label={`${needs} requests need input`} onClick={()=>setActive('My Requests')}><Bell size={19}/>{needs>0&&<i>{needs}</i>}</button>}<div className="user"><div className="avatar">{initials(user.name)}</div><div><b>{user.name}</b><small>{user.role}</small></div></div><button className="logout" type="button" aria-label="Sign out" onClick={logout}><LogOut size={18}/></button></div></header><nav className="topNav" aria-label="Main navigation">{nav.map(([n,I])=><button key={n} type="button" className={active===n?'topNavLink active':'topNavLink'} aria-current={active===n?'page':undefined} onClick={()=>setActive(n)}><I size={17}/><span>{n}</span></button>)}</nav><section className="content">{error&&<div className="error" role="alert">{error}<button type="button" aria-label="Dismiss error" onClick={()=>setError('')}><X size={15}/></button></div>}<div className="simulation"><ShieldCheck size={16}/>Microsoft handles organization password actions. Software and application access remain simulated.</div>
 {active==='Dashboard'&&user.role==='admin'&&<MemoManagerDashboard requests={filteredAdminRequests} users={admin.users} devices={admin.devices} onEnroll={openEnrollment}/>}{active==='Dashboard'&&user.role!=='admin'&&<><div className="dashboardHero"><div><span className="eyebrow">YOUR IT WORKSPACE</span><h1>Welcome back, {user.name.split(' ')[0]}</h1><p>Describe your issue below. Follow its progress in My Requests.</p></div><div className="heroDate"><Clock3 size={18}/><span>{new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span></div></div><div className="stats">{[['Total requests',requests.length,Ticket,'All your submitted requests'],['Resolved',resolved,CheckCircle2,'Completed requests'],['In progress',progress,Clock3,'Waiting or being handled'],['Needs input',needs,AlertCircle,'Your reply is needed']].map(([n,v,I,detail],i)=><div className="stat" key={n}><div className={'statIcon s'+i}><I size={19}/></div><span>{n}</span><b>{v}</b><small>{detail}</small></div>)}</div><div className="dashboardChat"><Chat full chat={chat} msg={msg} setMsg={setMsg} send={send} busy={busy} retryAfter={retryAfter} devices={devices} selected={selectedDevice} setSelected={setSelectedDevice} clarify={clarify} cancel={()=>setClarify(null)} passwordAction={passwordAction}/></div></>}
 {user.role!=='admin'&&active==='My Requests'&&<Requests rows={filtered} open={setModal} passwordAction={passwordAction} busy={busy} reply={id=>{setClarify(id);setActive('Dashboard')}}/>}
 {user.role!=='admin'&&active==='Knowledge Base'&&<Knowledge/>}{user.role!=='admin'&&active==='Settings'&&<Profile user={user} devices={devices}/>}
 {user.role==='admin'&&active==='Admin Panel'&&<Admin data={admin} catalog={catalog} enrollment={enrollment} setEnrollment={setEnrollment} act={act} busy={busy} api={api} refresh={refreshAdmin}/>} {user.role==='admin'&&active==='Audit Logs'&&<Audit rows={admin.audit}/>} {active==='Application Access'&&(user.role==='admin'?<AdminAccess api={api}/>:<EmployeeAccess api={api}/>)}</section></main>{modal&&<RequestModal row={modal} close={()=>setModal(null)} api={api}/>}</div>
}

function Brand(){return <div className="brand"><div className="brandIcon"><img src="/logo.png?v=2" alt=""/></div><div><b>AutoDeskAI</b><small>AI Powered IT Helpdesk</small></div></div>}
function ThemeToggle({theme,setTheme}){return <button className="themeToggle" type="button" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={`Switch to ${theme==='dark'?'light':'dark'} mode`} title={`Switch to ${theme==='dark'?'light':'dark'} mode`}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button>}
function Auth({mode,setMode,submit,busy,error,authRole,setAuthRole,theme,setTheme}){
 const isManager=authRole==='admin';
 const [showRecovery,setShowRecovery]=useState(false),[showPassword,setShowPassword]=useState(false),[recoveryError,setRecoveryError]=useState(''),[recoveryDestination,setRecoveryDestination]=useState(''),[recoveryLoading,setRecoveryLoading]=useState(false);
 const openRecovery=async()=>{setShowRecovery(true);setRecoveryError('');setRecoveryDestination('');setRecoveryLoading(true);try{const result=await requestApi('/auth/password-recovery');const destination=result?.available?validatedSsprUrl(result.url):null;if(!destination){setRecoveryError('Organization password recovery is not configured correctly. Contact your IT administrator for help.');return}setRecoveryDestination(destination)}catch{setRecoveryError('Unable to load organization password recovery settings. Please try again.')}finally{setRecoveryLoading(false)}};
 const openSspr=()=>{if(busy||recoveryLoading||!recoveryDestination)return;const destination=validatedSsprUrl(recoveryDestination);if(!destination){setRecoveryDestination('');setRecoveryError('Organization password recovery is not configured correctly. Contact your IT administrator for help.');return}window.location.assign(destination)};
 const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);
 const latestBirthDate=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;
 const changeMode=next=>{setMode(next);setShowRecovery(false)};
 return <div className={'authPage '+(mode==='register'?'registerPage':'')}>
  <section className="authHero">
   <div className="authBrandRow"><Brand/><ThemeToggle theme={theme} setTheme={setTheme}/></div>
   <div className="authHeroInner">
    <div className="authHeroCopy"><span className="authEyebrow">A CLEARER WAY TO GET SUPPORT</span><h1>IT help that keeps your day moving.</h1><p>Ask for help, follow your requests, and see what happens next in one calm workspace.</p></div>
    <div className="heroPoints"><span><ShieldCheck size={18}/>Protected actions</span><span><Activity size={18}/>Visible progress</span><span><Bot size={18}/>Guided requests</span></div>
   </div>
  </section>
  <section className={'authCard '+(mode==='register'?'register':'')}><div className="authPanel">
   <div className="authModeTabs" role="group" aria-label="Account action"><button type="button" disabled={busy} className={mode==='login'?'active':''} aria-pressed={mode==='login'} onClick={()=>changeMode('login')}>Sign in</button><button type="button" disabled={busy} className={mode==='register'?'active':''} aria-pressed={mode==='register'} onClick={()=>changeMode('register')}>Create account</button></div>
   <div className="authRoleLabel">Choose your workspace</div>
   <div className="authTabs" role="group" aria-label="Account type">
    <button type="button" disabled={busy} className={authRole==='employee'?'authTab active':'authTab'} aria-pressed={authRole==='employee'} onClick={()=>{setAuthRole('employee');setShowRecovery(false)}}><UserCircle2 size={19}/><span><b>Employee</b><small>Get IT support</small></span></button>
    <button type="button" disabled={busy} className={authRole==='admin'?'authTab active':'authTab'} aria-pressed={authRole==='admin'} onClick={()=>{setAuthRole('admin');setShowRecovery(false)}}><ShieldCheck size={19}/><span><b>Administrator</b><small>Manage the desk</small></span></button>
   </div>
   {showRecovery?<div className="recoveryNotice"><span className="authEyebrow">ACCOUNT HELP</span><h2>Forgot organization password?</h2><p>Continue to Microsoft to verify your identity and reset your work or school password. AutoDeskAI never receives your organization password.</p>{recoveryLoading&&<p role="status">Checking recovery configuration…</p>}{recoveryError&&<p className="error" role="alert">{recoveryError}</p>}<p>If Microsoft says self-service recovery is unavailable, contact your organization's IT administrator.</p><button type="button" className="primary" disabled={busy||recoveryLoading||!recoveryDestination} onClick={openSspr}>Continue to Microsoft password reset</button><button type="button" className="authRecoveryLink" onClick={()=>{setRecoveryError('');setRecoveryDestination('');setShowRecovery(false)}}>Back to sign in</button></div>:<>
    <div className="authHeading"><span className="authEyebrow">{mode==='register'?'NEW ACCOUNT':'WELCOME BACK'}</span><h2>{mode==='login'?(isManager?'Administrator sign in':'Sign in to your workspace'):isManager?'Create an administrator account':'Create your employee account'}</h2><p>{mode==='login'?'Use your username or registered email to continue.':isManager?'You will need the private invite code from your organization.':'Your service desk profile starts here.'}</p></div>
    {error&&<div className="error" role="alert">{error}</div>}
    <form onSubmit={submit} aria-busy={busy} className={mode==='register'?'registrationForm':''}>
     {mode==='register'&&<>
      <div className="formSectionTitle"><span>01</span><div><b>Personal details</b><small>Tell us who you are</small></div></div>
      <div className="formPair"><label>First name<input name="first_name" required maxLength="50" autoComplete="given-name" placeholder="First name"/></label><label>Last name<input name="last_name" required maxLength="50" autoComplete="family-name" placeholder="Last name"/></label></div>
      <div className="formPair"><label>Date of birth<input name="date_of_birth" type="date" required max={latestBirthDate} autoComplete="bday"/></label><label>Username<input name="username" required minLength="3" maxLength="50" pattern="[a-zA-Z][a-zA-Z0-9._-]*" title="Start with a letter; use letters, numbers, dots, underscores, or hyphens." autoComplete="username" placeholder="Choose a username"/></label></div>
      <div className="formSectionTitle"><span>02</span><div><b>Account access</b><small>Keep your sign in details private</small></div></div>
      <label>Email address<input name="email" type="email" required maxLength="150" autoComplete="email" placeholder="you@company.com"/></label>
      {isManager&&<label>Administrator invite code<input name="admin_invite_code" type="password" required maxLength="256" autoComplete="off" placeholder="Code from your organization"/></label>}
     </>}
     {mode==='login'&&<label>Username or email<input name="identifier" required maxLength="150" autoComplete="username" placeholder="you@company.com or username"/></label>}
     <label>Password<div className="passwordField"><input name="password" type={showPassword?'text':'password'} required minLength={mode==='register'?6:1} maxLength="256" autoComplete={mode==='login'?'current-password':'new-password'} placeholder={mode==='register'?'Create a password':'Enter your password'}/><button type="button" className="passwordToggle" aria-label={showPassword?'Hide password':'Show password'} aria-pressed={showPassword} onClick={()=>setShowPassword(value=>!value)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>
     {mode==='register'&&<><label>Confirm password<input name="confirm_password" type={showPassword?'text':'password'} required minLength="6" maxLength="256" autoComplete="new-password" placeholder="Repeat your password"/></label><small className="formHelp">Use at least 6 characters.</small></>}
     <button className="primary authSubmit" disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in':isManager?'Create administrator account':'Create employee account'}</button>
    </form>
    {mode==='login'&&<button type="button" className="authRecoveryLink" disabled={busy} onClick={()=>void openRecovery()}>Forgot organization password?</button>}
   </>}
   <div className="authPanelFoot"><ShieldCheck size={15}/>Your account is protected by role based access.</div>
  </div></section>
 </div>;
}
function Chat({chat,msg,setMsg,send,busy,retryAfter=0,devices,selected,setSelected,clarify,cancel,full,passwordAction}){
 const chatLog=useRef(null);
 const composer=chatComposerState(msg,busy,retryAfter);
 useEffect(()=>{if(chatLog.current)chatLog.current.scrollTop=chatLog.current.scrollHeight},[chat.length,busy]);
 const hasRequests=chat.some(message=>message.r==='user');
 return <section className={'card assistant '+(full?'full':'')} aria-label="AI Assistant">
  <div className="cardHead"><div className="title"><div className="bot"><Bot size={21}/></div><div><b>AI Assistant</b><small>Ask a question or describe one IT request.</small></div></div><span className="online"><i/>{busy?'Working':'Ready to help'}</span></div>
  <div className="chatIntro"><b>How can I help?</b><span>Chat naturally or ask about password help, approved software, or application access. Never enter credentials here.</span>{!hasRequests&&<div className="suggestions"><button type="button" onClick={()=>send('I forgot my password')} disabled={busy}>Reset my password</button><button type="button" onClick={()=>send('Install VS Code')} disabled={busy||!selected} title={!selected?'Select an installation device first':undefined}>Install VS Code</button><button type="button" onClick={()=>send('I need access to Tableau')} disabled={busy}>Request Tableau access</button></div>}</div>
  <div className="deviceBar"><label htmlFor={full?'chat-device-full':'chat-device-dashboard'}>Installation device<select id={full?'chat-device-full':'chat-device-dashboard'} value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select a registered device</option>{devices.filter(x=>x.status==='ACTIVE').map(x=><option value={x.id} key={x.id}>{x.hostname} · {x.os_info}</option>)}</select></label>{!devices.length&&<small>An administrator must enroll your device before installation.</small>}</div>
  <div className="chat" ref={chatLog} role="log" aria-live="polite" aria-label="Conversation">{chat.map((m,i)=><div className={m.r==='user'?'row user':'row'} key={i}>{m.r==='bot'&&<div className="mini bot"><Bot size={15}/></div>}<div className="bubble">{m.t}{m.status&&<small>{requestStatusLabel(m.status)}</small>}{m.status==='AWAITING_USER_ACTION'&&<button type="button" disabled={busy} onClick={()=>passwordAction(m.id)}>Continue at Microsoft</button>}</div>{m.r==='user'&&<div className="mini person"><UserCircle2 size={20}/></div>}</div>)}{busy&&<div className="row"><div className="mini bot"><Bot size={15}/></div><div className="bubble">Thinking…</div></div>}</div>
  {clarify&&<div className="clarify">Adding information to your request<button type="button" onClick={cancel}>Cancel</button></div>}
  <form className="composer" onSubmit={e=>{e.preventDefault();if(!composer.disabled)send()}}><textarea aria-label="Your message" value={msg} onChange={e=>setMsg(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();if(!composer.disabled)send()}}} maxLength={CHAT_MESSAGE_LIMIT} rows="2" placeholder="Describe what you need help with…"/><button className="send" type="submit" aria-label="Send message" disabled={composer.disabled}><span>Send</span><Send size={17}/></button></form>
  <small className="composerHint">{composer.hint} · {composer.count}/{CHAT_MESSAGE_LIMIT} · Enter to send · Shift+Enter for a new line</small>
 </section>
}
const requestStatusLabel=status=>({PENDING:'In Progress',PROCESSING:'In Progress',COMPLETED:'Complete',REJECTED:'Rejected',AWAITING_USER_ACTION:'Waiting for User Action',AWAITING_ADMIN:'Awaiting Administrator',APPROVED_PROVISIONING_REQUIRED:'Approved · Provisioning Required',NEEDS_CLARIFICATION:'Waiting for Your Information',FAILED:'Failed'}[status]||label(status));
function requestDescription(row){const input=(row.original_message||'').toLowerCase();if(input.includes('password')&&input.includes('forgot'))return'Organization password reset';if(input.includes('password')&&input.includes('change'))return'Organization password change';if(input.includes('install')&&input.includes('vscode'))return'Install Visual Studio Code';if(input.includes('access')&&input.includes('tableau'))return'Request access to Tableau';return row.original_message&&row.original_message!=='[not retained]'?row.original_message:row.message||'No description provided';}
function Requests({rows,open,passwordAction,reply,busy}) {
 return <section className="pageCard requestsPage">
  <PageTitle title="My Requests" text="Track each request and take action when more information is needed." icon={Ticket}/>
  <div className="listSummary">{rows.length} {rows.length===1?'request':'requests'}</div>
  <PaginatedRows rows={rows}>{pageRows=>pageRows.length?<div className="requestsTableWrap"><table className="requestsTable"><thead><tr><th scope="col">Request type</th><th scope="col">Description</th><th scope="col">Status</th><th scope="col">Date &amp; time</th><th scope="col">Action</th></tr></thead><tbody>{pageRows.map(row=>{const passwordPending=row.status==='AWAITING_USER_ACTION'&&row.intent.startsWith('PASSWORD_'),needsReply=row.status==='NEEDS_CLARIFICATION';return <tr key={row.id}><td data-label="Request type">{title(row)}</td><td className="requestDescriptionCell" data-label="Description">{requestDescription(row)}</td><td data-label="Status"><span className={'status '+row.status.toLowerCase()}>{requestStatusLabel(row.status)}</span></td><td data-label="Date & time"><time dateTime={row.created_at}>{formatDate(row.created_at)}</time></td><td data-label="Action" className="requestTableAction">{passwordPending?<button type="button" className="requestAction" disabled={busy} onClick={()=>passwordAction(row.id)}>{busy?'Opening…':row.intent==='PASSWORD_CHANGE'?'Continue at Microsoft My Account':'Open Microsoft password reset'}</button>:needsReply?<button type="button" className="requestAction" disabled={busy} onClick={()=>reply(row.id)}>Provide information</button>:<button type="button" className="requestAction" onClick={()=>open(row)}>View details</button>}</td></tr>})}</tbody></table></div>:<div className="empty">No requests match your search.</div>}</PaginatedRows>
 </section>;
}
function Knowledge(){return <section className="pageCard knowledgePage">
 <PageTitle title="Knowledge Base" text="How supported requests move from AutoDeskAI to the right service." icon={BookOpen}/>
 <div className="knowledgeLead"><KeyRound size={21}/><div><b>Organization password help</b><p>Start a request in the dashboard chat. AutoDeskAI records it and sends you to Microsoft for the actual password action. Enter passwords and verification codes only on Microsoft's pages.</p></div></div>
 <div className="knowledgeFlows">
  <article className="knowledgeFlow"><div className="knowledgeFlowHead"><span className="knowledgeIcon"><KeyRound size={20}/></span><div><small>WHEN YOU KNOW YOUR CURRENT PASSWORD</small><h2>Change your password</h2></div></div>
   <ol><li>Sign in to AutoDeskAI as an employee and ask the dashboard chat to change your work or school password.</li><li>The request appears in My Requests as <b>Awaiting User Action</b>. Select <b>Continue at Microsoft My Account</b> in the request or chat.</li><li>Sign in to Microsoft My Account with your work or school account and its current password. Choose <b>Change Password</b>.</li><li>Enter your old password, create and confirm the new one, then select <b>Submit</b>. Microsoft may ask you to sign in again.</li></ol>
   <a href="https://support.microsoft.com/en-us/accounts-billing/work-school/change-your-work-or-school-account-password" target="_blank" rel="noopener noreferrer">Read Microsoft's change instructions</a>
  </article>
  <article className="knowledgeFlow"><div className="knowledgeFlowHead"><span className="knowledgeIcon"><ShieldCheck size={20}/></span><div><small>WHEN YOU FORGOT YOUR PASSWORD</small><h2>Reset your password</h2></div></div>
   <ol><li>While signed in to AutoDeskAI, ask the dashboard chat to reset your work or school password.</li><li>Open the request in My Requests and select <b>Open Microsoft password reset</b>.</li><li>On Microsoft's page, enter your work or school account and complete the identity checks using your registered recovery methods.</li><li>If your organization has enabled self-service reset for your account, set a new password on Microsoft's page. Otherwise, contact your IT administrator.</li></ol>
   <a href="https://support.microsoft.com/en-us/accounts-billing/work-school/reset-your-microsoft-work-or-school-account-password-using-security-info" target="_blank" rel="noopener noreferrer">Read Microsoft's reset instructions</a>
  </article>
 </div>
 <div className="knowledgeNotice"><AlertCircle size={20}/><div><h2>What happens to the request?</h2><p>AutoDeskAI checks that the request belongs to you and records when the Microsoft link is issued. Microsoft does not send the result back, so the request stays <b>Awaiting User Action</b> even if you finish there. Your AutoDeskAI sign-in password is separate; if you cannot sign in here, contact your IT administrator.</p></div></div>
 <div className="knowledgeRelated"><article><MonitorDown size={21}/><div><h3>Software installation</h3><p>Select an active registered device in chat, then request approved software. Its endpoint agent must be online.</p></div></article><article><Grid2X2 size={21}/><div><h3>Application access</h3><p>Ask in chat. Backend policy decides whether access is allowed; chat cannot grant it.</p></div></article></div>
 </section>}
function Profile({user,devices}){return <section className="pageCard"><PageTitle title="Profile & Settings" text="Your session stays active when you reload this tab." icon={Settings}/><div className="profile"><div className="bigAvatar">{initials(user.name)}</div><div><h2>{user.name}</h2><p>{user.username?`@${user.username} · ${user.email}`:user.email}</p><span className="role">{user.role}</span></div></div><h2>Registered devices</h2>{devices.length?<PaginatedRows rows={devices}>{pageRows=>pageRows.map(x=><Device row={x} key={x.id}/>)}</PaginatedRows>:<div className="empty">No devices assigned.</div>}</section>}
function Device({row,action}){return <div className="device"><Laptop/><div><b>{row.hostname}</b><small>{row.device_id} · {row.os_info} · owner #{row.owner_user_id}</small></div>{action?<button onClick={action}>{row.status==='ACTIVE'?'Disable':'Enable'}</button>:<span className={'status '+row.status.toLowerCase()}>{row.status}</span>}</div>}
function Admin({data,catalog,enrollment,setEnrollment,act,busy,api,refresh}){const employees=(data.users||[]).filter(user=>user.role!=='admin');return <div className="adminGrid"><section className="pageCard"><PageTitle title="Admin Panel" text="Manage predefined capabilities and devices." icon={Users}/><h2>Approved software</h2>{catalog.software.map(x=><div className="policy" key={x.key}><span><b>{x.display_name}</b><small>{x.key}</small></span><button onClick={()=>act(async()=>{await api('/admin/software/'+x.key,{method:'PUT',body:JSON.stringify({enabled:!x.enabled,required_role:'employee'})});await refresh(['catalog'])})}>{x.enabled?'Disable':'Enable'}</button></div>)}<h2>Application policies</h2>{catalog.applications.map(x=><div className="policy" key={x.key}><span><b>{x.key}</b><small>{x.enabled?'Enabled':'Disabled'}</small></span><select value={x.required_role} onChange={e=>act(async()=>{await api('/admin/applications/'+x.key,{method:'PUT',body:JSON.stringify({enabled:x.enabled,required_role:e.target.value})});await refresh(['catalog'])})}><option value="employee">Employees and admins</option><option value="admin">Admins only</option></select><button onClick={()=>act(async()=>{await api('/admin/applications/'+x.key,{method:'PUT',body:JSON.stringify({enabled:!x.enabled,required_role:x.required_role})});await refresh(['catalog'])})}>{x.enabled?'Disable':'Enable'}</button></div>)}</section><section className="pageCard"><div className="sectionHead"><div><h2>Endpoint devices</h2><p>{data.devices.filter(deviceOnline).length} connected · {data.devices.length} enrolled</p></div></div>{data.devices.length?<PaginatedRows rows={data.devices}>{pageRows=>pageRows.map(device=><div className="endpointAdminRow" key={device.id}><div className="endpointIdentity"><Laptop size={19}/><span><b>{device.hostname}</b><small>{device.device_id} · {(data.users||[]).find(owner=>owner.id===device.owner_user_id)?.name||'Unknown owner'} · {device.os_info}</small><small>Last seen {formatDate(device.last_seen)}</small></span></div><span className={`connectionStatus ${device.status==='ACTIVE'?(deviceOnline(device)?'connected':'offline'):'disabled'}`}>{device.status==='DISABLED'?'Disabled':deviceOnline(device)?'Connected':'Offline'}</span><button type="button" className="deviceToggle" disabled={busy} onClick={()=>act(async()=>{await api(`/admin/devices/${device.id}`,{method:'PATCH',body:JSON.stringify({status:device.status==='ACTIVE'?'DISABLED':'ACTIVE'})});await refresh(['devices'])})}>{device.status==='ACTIVE'?'Disable':'Enable'}</button></div>)}</PaginatedRows>:<div className="empty">No endpoint devices enrolled yet.</div>}</section><section className="pageCard enrollCard"><div className="sectionHead"><div><h2>Add endpoint device</h2><p>Enroll an agent and assign it to an employee.</p></div><Laptop size={23}/></div><form onSubmit={e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);act(async()=>{setEnrollment(await api('/agent/register',{method:'POST',body:JSON.stringify({owner_user_id:Number(f.get('owner')),device_id:f.get('device_id'),hostname:f.get('hostname'),os_info:f.get('os_info')})}));await refresh(['devices']);form.reset()})}}><label>Owner<select name="owner" required defaultValue=""><option value="" disabled>Select an employee</option>{employees.map(x=><option value={x.id} key={x.id}>{x.name} · {x.email}</option>)}</select></label><label>Device ID<input name="device_id" pattern="[a-zA-Z0-9_.-]+" required placeholder="e.g. LAPTOP-014"/></label><label>Hostname<input name="hostname" pattern="[a-zA-Z0-9_.-]+" required placeholder="e.g. THARUN-LAPTOP"/></label><label>Operating system<select name="os_info"><option>Windows</option><option>Linux</option><option>Darwin</option><option>Test</option></select></label><button className="primary" type="submit" disabled={busy||!employees.length}>Enroll endpoint</button>{enrollment&&<div className="tokenBox"><b>Agent token</b><code>{enrollment.agent_token}</code><small>Copy and store it securely. This token is shown once only.</small></div>}</form></section></div>}
const MemoManagerDashboard=React.memo(ManagerDashboard);
function ManagerDashboard({requests=[],users=[],devices=[],onEnroll}){const[employeeFilter,setEmployeeFilter]=useState('all'),[deviceFilter,setDeviceFilter]=useState('all');const employeeUsers=users.filter(user=>user.role!=='admin');const userMap=Object.fromEntries(users.map(user=>[user.id,user]));const requestCounts={},deviceCounts={},endpointCounts={};for(const request of requests){requestCounts[request.user_id]=(requestCounts[request.user_id]||0)+1;if(request.task)endpointCounts[request.task.device_id]=(endpointCounts[request.task.device_id]||0)+1}for(const device of devices)deviceCounts[device.owner_user_id]=(deviceCounts[device.owner_user_id]||0)+1;const statuses=[['Pending',['PENDING','PROCESSING','NEEDS_CLARIFICATION','AWAITING_ADMIN','APPROVED_PROVISIONING_REQUIRED'],'chartPending'],['Closed',['COMPLETED','FAILED','REJECTED'],'chartClosed'],['Other',['CANCELLED'],'chartOther']];const countStatus=values=>requests.filter(request=>values.includes(request.status)).length;const pending=countStatus(statuses[0][1]);const closed=countStatus(statuses[1][1]);const connected=devices.filter(deviceOnline).length;const visibleRequests=requests.filter(request=>(employeeFilter==='all'||String(request.user_id)===employeeFilter)&&(deviceFilter==='all'||String(request.task?.device_id)===deviceFilter));const total=Math.max(requests.length,1);return <div className="managerDashboard"><div className="intro"><div><h1>Manager Dashboard</h1><p>Track service requests and the endpoint systems handling software work.</p></div><div className="date">{employeeUsers.length} employees<br/><b>{requests.length} total requests</b></div></div><div className="managerStats"><div className="managerMetric"><Users/><span>Employees</span><strong>{employeeUsers.length}</strong></div><div className="managerMetric"><Ticket/><span>Total requests</span><strong>{requests.length}</strong></div><div className="managerMetric pendingMetric"><Clock3/><span>Pending</span><strong>{pending}</strong></div><div className="managerMetric closedMetric"><CheckCircle2/><span>Closed</span><strong>{closed}</strong></div><div className="managerMetric connectedMetric"><Laptop/><span>Connected endpoints</span><strong>{connected}<small> / {devices.length} enrolled</small></strong></div></div><div className="managerColumns"><section className="pageCard managerChart"><PageTitle title="Request status" text="Live distribution across all employee tickets." icon={Activity}/>{statuses.map(([name,values,className])=>{const count=countStatus(values);return <div className="chartLine" key={name}><div><b>{name}</b><span>{count} · {Math.round(count/total*100)}%</span></div><div className="chartTrack"><i className={className} style={{width:`${count/total*100}%`}}/></div></div>})}<div className="chartLegend"><span><i className="legendPending"/>Pending / in progress</span><span><i className="legendClosed"/>Closed</span></div></section><section className="pageCard managerEmployees"><PageTitle title="Employees" text="Select an employee to filter their requests." icon={Users}/><div className="employeeList"><button className={employeeFilter==='all'?'employeeItem selected':'employeeItem'} onClick={()=>setEmployeeFilter('all')}><div className="employeeAvatar">All</div><div className="employeeIdentity"><b>All employees</b><small>{employeeUsers.length} accounts</small></div><strong>{requests.length}</strong></button><PaginatedRows rows={employeeUsers}>{pageRows=>pageRows.map(employee=>{const employeeRequestCount=requestCounts[employee.id]||0,deviceCount=deviceCounts[employee.id]||0;return <button key={employee.id} className={employeeFilter===String(employee.id)?'employeeItem selected':'employeeItem'} onClick={()=>setEmployeeFilter(String(employee.id))}><div className="employeeAvatar">{initials(employee.name)}</div><div className="employeeIdentity"><b>{employee.name}</b><small>{employee.email}</small><small>{deviceCount} registered {deviceCount===1?'device':'devices'}</small></div><strong>{employeeRequestCount}</strong></button>})}</PaginatedRows>{!employeeUsers.length&&<div className="empty">No employee accounts found.</div>}</div></section></div><section className="pageCard endpointPanel"><div className="sectionHead"><div><h2>Endpoint systems</h2><p>{connected} connected · {devices.length-connected} offline or disabled · 2 minute heartbeat window</p></div><button type="button" className="secondary" onClick={onEnroll}>Add endpoint device</button></div><div className="endpointGrid"><PaginatedRows rows={devices}>{pageRows=>pageRows.map(device=>{const count=endpointCounts[device.id]||0;const status=device.status==='DISABLED'?'disabled':deviceOnline(device)?'connected':'offline';return <button type="button" className={`endpointCard ${deviceFilter===String(device.id)?'selected':''}`} key={device.id} onClick={()=>setDeviceFilter(deviceFilter===String(device.id)?'all':String(device.id))}><span className="endpointCardTop"><span className="endpointIcon"><Laptop size={18}/></span><span className={`connectionStatus ${status}`}>{status==='disabled'?'Disabled':status==='connected'?'Connected':'Offline'}</span></span><b>{device.hostname}</b><small>{device.device_id} · {device.os_info}</small><small>Owner: {userMap[device.owner_user_id]?.name||`User #${device.owner_user_id}`}</small><span className="endpointCardFoot"><span>{count} device {count===1?'request':'requests'}</span><span>{formatShortDate(device.last_seen)}</span></span></button>})}</PaginatedRows>{!devices.length&&<div className="empty">No endpoint systems enrolled. Add one to begin tracking device work.</div>}</div></section><section className="pageCard managerTicketPanel"><div className="sectionHead"><div><PageTitle title={deviceFilter==='all'?(employeeFilter==='all'?'All requests':`Requests for ${userMap[Number(employeeFilter)]?.name||'employee'}`):`Endpoint requests · ${devices.find(device=>String(device.id)===deviceFilter)?.hostname||'device'}`} text={deviceFilter==='all'?'All employee requests; select an endpoint card to view its assigned work.':'Requests assigned to this endpoint agent.'} icon={FileText}/></div>{deviceFilter!=='all'&&<button type="button" className="textButton" onClick={()=>setDeviceFilter('all')}>Show all requests</button>}</div><div className="ticketTable"><div className="ticketHead"><b>Ticket</b><b>Employee</b><b>Opened</b><b>Reason</b><b>Status</b><b>Closed</b></div>{visibleRequests.length?<PaginatedRows rows={visibleRequests}>{pageRows=>pageRows.map(request=>{const employee=userMap[request.user_id];const isClosed=statuses[1][1].includes(request.status);const endpoint=devices.find(device=>String(device.id)===String(request.task?.device_id));return <div className="ticketRow" key={request.id}><span data-label="Ticket">#{request.id} · {label(request.intent)}</span><span data-label="Employee"><b>{employee?.name||`User #${request.user_id}`}</b><small className="employeeEmail">{employee?.email||''}</small></span><span data-label="Opened">{formatDate(request.created_at)}</span><span className="ticketReason" data-label="Reason">{request.message||request.original_message||'No details provided'}{deviceFilter==='all'&&endpoint&&<small className="requestEndpoint">Endpoint: {endpoint.hostname}</small>}</span><span data-label="Status" className={'status '+request.status.toLowerCase()}>{label(request.status)}</span><span data-label="Closed">{isClosed?formatDate(request.updated_at):'Open'}</span></div>})}</PaginatedRows> : <div className="empty">No requests assigned to this endpoint.</div>}</div></section></div>}
function Audit({rows}){return <section className="pageCard"><PageTitle title="Audit Logs" text="Backend-owned records contain no credentials." icon={Activity}/><div className="listSummary">{rows.length} {rows.length===1?'event':'events'}</div><div className="auditTable"><div className="auditHead"><b>Time</b><b>Action</b><b>User</b><b>Status</b></div>{rows.length?<PaginatedRows rows={rows}>{pageRows=>pageRows.map(x=><div className="auditEntry" key={x.id}><span data-label="Time">{formatDate(x.timestamp)}</span><b data-label="Action">{x.action.replaceAll('_',' ')}</b><span data-label="User">{x.user_id||'System'}</span><span data-label="Status"><span className={'status '+x.status.toLowerCase()}>{label(x.status)}</span></span></div>)}</PaginatedRows>:<div className="empty">No audit events yet.</div>}</div></section>}function PageTitle({title:heading,text,icon:I}){return <div className="pageTitle"><div><h1>{heading}</h1><p>{text}</p></div><I/></div>}
function RequestModal({row,close,api}){
 const [history,setHistory]=useState([]),[failure,setFailure]=useState(''),[loading,setLoading]=useState(true);
 const closeButton=useRef(null);
 useEffect(()=>{const controller=new AbortController();setHistory([]);setFailure('');setLoading(true);Promise.resolve().then(async()=>{if(controller.signal.aborted)return;try{const items=await api(`/requests/${row.id}/history`,{signal:controller.signal});if(!controller.signal.aborted)setHistory(items)}catch(error){if(!controller.signal.aborted)setFailure(error.message)}finally{if(!controller.signal.aborted)setLoading(false)}});return()=>controller.abort()},[row.id,api]);
 const closeRef=useRef(close);closeRef.current=close;
 useEffect(()=>{const previous=document.activeElement;closeButton.current?.focus();const onKey=event=>{if(event.key==='Escape')closeRef.current();if(event.key==='Tab'){event.preventDefault();closeButton.current?.focus()}};window.addEventListener('keydown',onKey);return()=>{window.removeEventListener('keydown',onKey);if(previous?.isConnected)previous.focus()}},[]);
 return <div className="modalBg" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="request-dialog-title"><button className="x" ref={closeButton} type="button" aria-label="Close request details" onClick={close}><X/></button><div className="modalIcon"><Ticket/></div><small>REQUEST DETAILS</small><h2 id="request-dialog-title">{title(row)}</h2><p>{row.message}</p><span className={'status '+row.status.toLowerCase()}>{requestStatusLabel(row.status)}</span><div className="note"><ShieldCheck size={17}/>Backend policy and authorization determine this result.</div><h3>History</h3>{failure&&<p className="error">{failure}</p>}{loading?<div className="empty">Loading history…</div>:history.length?<PaginatedRows rows={history}>{pageRows=>pageRows.map(x=><div className="history" key={x.id}><b>{x.action.replaceAll('_',' ')}</b><small>{formatDate(x.timestamp)} · {requestStatusLabel(x.status)}</small></div>)}</PaginatedRows>:!failure&&<div className="empty">No history yet.</div>}</div></div>
}
